<script setup lang="ts">
import { computed,defineAsyncComponent,nextTick,onMounted,onUnmounted,ref,shallowRef,watch } from 'vue';
import { VueFlow,useVueFlow,MarkerType,SelectionMode,type Node,type Connection,type NodeMouseEvent,type NodeDragEvent,type NodeChange,type EdgeMouseEvent } from '@vue-flow/core';
import { Background } from '@vue-flow/background';
import { MiniMap } from '@vue-flow/minimap';
import { ElMessageBox } from 'element-plus';
import { ElMessage } from '@/utils/message';
import type { ShortDramaDetail } from '@/api/shortDrama/types';
import type { GetSessionListVO } from '@/api/model/types';
import { uploadReferenceImage } from '@/api/shortDrama';
import { readShortDramaResource } from '@/api/shortDrama/resources';
import { buildDramaFlowGraph,type FlowAsset } from '@/utils/dramaFlowGraph';
import { copyCanvas,newCanvasNode,canvasInputs,connectionIssue,cloneCanvasSelection,removeCanvasNodes,groupCanvasSelection,validateCanvas,type CanvasKind,type CanvasNode,type CanvasData,type CanvasDocument } from '@/utils/dramaCanvas';
import type { FlowActions } from './types';
import {useCanvasDocument} from './useCanvasDocument';
import {useCanvasExecution} from './useCanvasExecution';
import CanvasToolbar from './CanvasToolbar.vue';
import CanvasNodeCard from './CanvasNodeCard.vue';
import CanvasInspector from './CanvasInspector.vue';
import CanvasContextMenu from './CanvasContextMenu.vue';
import CanvasCompose from './CanvasCompose.vue';
const DirectorStudio=defineAsyncComponent(()=>import('../director/DirectorStudio.vue'));
import '@vue-flow/core/dist/style.css';
import '@vue-flow/core/dist/theme-default.css';
import '@vue-flow/minimap/dist/style.css';

const props=defineProps<{detail:ShortDramaDetail;actions:FlowActions;refresh:()=>Promise<void>;imageModels:GetSessionListVO[];videoModels:GetSessionListVO[]}>();
const emit=defineEmits<{close:[];new:[];references:[]}>();
const projectId=props.detail.project.id!;
const store=useCanvasDocument(projectId);
const doc=store.document;
const execution=useCanvasExecution({project:projectId,initial:()=>props.detail,document:()=>doc.value,patch:store.business,persist:store.save,actions:props.actions,refresh:props.refresh});
const {project,fitView,setViewport,viewport,zoomIn,zoomOut,setNodes,setEdges}=useVueFlow(`studio-${projectId}`);
const nodes=shallowRef<Node[]>([]),selectedIds=ref<string[]>([]),inspectorId=shallowRef(''),mode=shallowRef('workflow'),tool=shallowRef('select'),showEdges=shallowRef(true),composeOpen=shallowRef(false);
const root=ref<HTMLElement>(),pane=ref<HTMLElement>();
const directorId=shallowRef('');
const directorNode=computed(()=>doc.value.nodes.find(n=>n.id===directorId.value));
async function openDirector(id:string){if(!await store.save()){ElMessage.warning('请先保存流程画布，再打开导演台');return;}inspectorId.value=id;directorId.value=id;menu.value=undefined;}
function inspect(id:string){inspectorId.value=id;selectedIds.value=[id];if(doc.value.nodes.find(n=>n.id===id)?.kind==='previs')void openDirector(id);}
const menu=ref<{x:number;y:number;point:{x:number;y:number};target?:string;edge?:string;origin?:string}>();
let clipboard:CanvasDocument|undefined,connectionOrigin='',connected=false;
let groupOrigins=new Map<string,CanvasNode['position']>();
let initialized=false;
const selected=computed(()=>doc.value.nodes.find(n=>n.id===inspectorId.value));
const inputNodes=computed(()=>selected.value ? canvasInputs(doc.value,selected.value.id) : []);
const selectedShot=computed(()=>execution.detail.value.storyboards.find(s=>s.id===selected.value?.data.business?.id));
const selectedActor=computed(()=>execution.detail.value.characters.find(c=>c.id===selected.value?.data.business?.id));
const edges=computed(()=>showEdges.value ? doc.value.edges.map(e=>({ ...e,sourceHandle:'output',targetHandle:'input',selectable:true,label:doc.value.nodes.find(n=>n.id===e.source)?.kind==='video' ? '镜头顺序' : undefined,
  style:{stroke:inputNodes.value.some(n=>n.id===e.source) && e.target===inspectorId.value ? '#528bf0' : '#b3c3da',strokeWidth:1.5},markerEnd:{type:MarkerType.ArrowClosed,color:'#b3c3da',width:12,height:12}})) : []);
const videos=computed(()=>execution.orderedVideos());
const projectShotCount=computed(()=>props.detail.storyboards.filter(shot=>!props.detail.script?.id || shot.scriptId===props.detail.script.id).length);
const readyIds=computed(()=>execution.detail.value.storyboards.filter(s=>s.videoStatus==='done'&&s.videoUrl&&s.id).map(s=>s.id!));
function rebuild(){nodes.value=doc.value.nodes.map(n=>({id:n.id,type:'canvas',position:{...n.position},data:n,selected:selectedIds.value.includes(n.id),zIndex:n.kind==='group' ? 0 : 1,style:n.kind==='group' ? {width:`${n.data.width}px`,height:`${n.data.height}px`} : undefined}));setEdges([]);setNodes(nodes.value);setEdges(edges.value);}
watch(doc,rebuild,{deep:true});watch(selectedIds,rebuild);
watch(edges,()=>setEdges(edges.value),{flush:'post'});
function status(n:CanvasNode){if(n.kind==='video'&&n.data.business){const s=execution.detail.value.storyboards.find(s=>s.id===n.data.business!.id);return s?.videoStatus==='done' ? '已生成' : s?.videoStatus==='generating' ? '生成中' : s?.videoStatus==='failed' ? '失败' : undefined;}return n.data.job?.status;}
function patch(id:string,data:Partial<CanvasData>){store.replace({...doc.value,nodes:doc.value.nodes.map(n=>n.id===id ? {...n,data:{...n.data,...data}} : n)});}
function point(event:{clientX:number;clientY:number}){const rect=pane.value!.getBoundingClientRect();return project({x:event.clientX-rect.left,y:event.clientY-rect.top});}
function openMenu(event:MouseEvent,extra:Partial<NonNullable<typeof menu.value>>={}){if(!store.ready.value)return;event.preventDefault();menu.value={x:event.clientX,y:event.clientY,point:point(event),...extra};}
function nodeMenu({event,node}:NodeMouseEvent){if(!selectedIds.value.includes(node.id))selectedIds.value=[node.id];if(event instanceof MouseEvent)openMenu(event,{target:node.id});}
function edgeMenu({event,edge}:EdgeMouseEvent){if(event instanceof MouseEvent)openMenu(event,{edge:edge.id});}
function nodeClick({node}:NodeMouseEvent){inspectorId.value=node.id;menu.value=undefined;}
function selectionChanges(changes:NodeChange[]){const next=new Set(selectedIds.value);changes.forEach(c=>{if(c.type==='select'){if(c.selected)next.add(c.id);else next.delete(c.id);}});if([...next].join()!==selectedIds.value.join())selectedIds.value=[...next];}
function rememberDrag({nodes:moved,node}:NodeDragEvent){const moving=moved.length ? moved : [node];const positions=new Map(moving.map(n=>[n.id,{...n.position}]));
  for(const n of moving){const old=groupOrigins.get(n.id);if(old&&n.data.kind==='group')doc.value.nodes.filter(c=>c.parentId===n.id&&!positions.has(c.id)).forEach(c=>positions.set(c.id,{x:c.position.x+n.position.x-old.x,y:c.position.y+n.position.y-old.y}));}
  store.replace({...doc.value,nodes:doc.value.nodes.map(n=>positions.has(n.id) ? {...n,position:positions.get(n.id)!} : n)});groupOrigins.clear();}
function beginDrag(){groupOrigins=new Map(doc.value.nodes.filter(n=>n.kind==='group').map(n=>[n.id,{...n.position}]));}
function rememberView(){if(store.ready.value)store.replace({...doc.value,viewport:{...viewport.value}},false);}
async function initialize(){setEdges(edges.value);if(initialized)return;initialized=true;if(doc.value.viewport)await setViewport(doc.value.viewport);else if(doc.value.nodes.length)await fitView({padding:.2,maxZoom:.85});}
function canConnect(c:Connection){return !!c.source&&!!c.target&&!connectionIssue({...doc.value,edges:doc.value.edges.filter(e=>e.source!==c.source||e.target!==c.target)},c.source,c.target);}
function connect(c:Connection){if(!c.source||!c.target)return;const issue=connectionIssue(doc.value,c.source,c.target);if(issue){ElMessage.warning(issue);return;}store.replace({...doc.value,edges:[...doc.value.edges,{id:crypto.randomUUID(),source:c.source,target:c.target}]});connected=true;connectionOrigin='';}
function endConnection(event:MouseEvent|TouchEvent|undefined){if(!connected&&connectionOrigin&&event instanceof MouseEvent&&(event.target as Element)?.closest('.vue-flow__pane'))openMenu(event,{origin:connectionOrigin});connectionOrigin='';connected=false;}
async function add(kind:CanvasKind){const position=menu.value?.point || project({x:Math.max(150,(pane.value?.clientWidth || 1200)/2-150),y:120});const n=newCanvasNode(kind,position);if(kind==='image')n.data.model=props.imageModels[0]?.modelName || '';if(kind==='video'){n.data.model=props.videoModels[0]?.modelName || '';n.data.order=doc.value.nodes.filter(n=>n.kind==='video').length+1;n.data.resolution='720p';}const origin=menu.value?.origin;
  const next={...doc.value,nodes:[...doc.value.nodes,n]};if(origin){const issue=connectionIssue(next,origin,n.id);if(issue){ElMessage.warning(issue);return;}next.edges=[...next.edges,{id:crypto.randomUUID(),source:origin,target:n.id}];}
  store.replace(next);selectedIds.value=[n.id];inspectorId.value=n.id;menu.value=undefined;await nextTick();if(kind==='previs')await openDirector(n.id);}
function removeInput(source:string){if(selected.value)store.replace({...doc.value,edges:doc.value.edges.filter(e=>!(e.source===source&&e.target===selected.value!.id))});}
function attach(source:string){if(selected.value)connect({source,target:selected.value.id,sourceHandle:'output',targetHandle:'input'});}
async function overview(){await fitView({padding:.2,maxZoom:.9,duration:200});rememberView();}
async function focus(id:string){inspectorId.value=id;selectedIds.value=[id];mode.value='workflow';await nextTick();await fitView({nodes:[id],padding:.7,maxZoom:1,duration:200});}
function duplicate(){const part=cloneCanvasSelection(doc.value,selectedIds.value);store.replace({...doc.value,nodes:[...doc.value.nodes,...part.nodes],edges:[...doc.value.edges,...part.edges]});selectedIds.value=part.nodes.map(n=>n.id);inspectorId.value=part.nodes.find(n=>n.kind!=='group')?.id || '';}
function copy(){clipboard=copyCanvas({...doc.value,nodes:doc.value.nodes.filter(n=>selectedIds.value.includes(n.id)||selectedIds.value.includes(n.parentId || '')),edges:doc.value.edges.filter(e=>selectedIds.value.includes(e.target))});ElMessage.success('已复制节点与输入连线');}
function paste(){if(!clipboard)return;const part=cloneCanvasSelection(clipboard,clipboard.nodes.map(n=>n.id),{x:80,y:60});const alive=new Set([...doc.value.nodes,...part.nodes].map(n=>n.id));store.replace({...doc.value,nodes:[...doc.value.nodes,...part.nodes],edges:[...doc.value.edges,...part.edges.filter(e=>alive.has(e.source))]});selectedIds.value=part.nodes.map(n=>n.id);}
function group(){const result=groupCanvasSelection(doc.value,selectedIds.value);store.replace({...doc.value,nodes:[result.group,...result.nodes]});selectedIds.value=[result.group.id];inspectorId.value=result.group.id;}
function ungroup(){const ids=new Set(selectedIds.value.flatMap(id=>{const n=doc.value.nodes.find(n=>n.id===id);return n?.kind==='group' ? [id] : n?.parentId ? [n.parentId] : [];}));store.replace(removeCanvasNodes(doc.value,[...ids]));selectedIds.value=[];inspectorId.value='';}
function remove(){store.replace(removeCanvasNodes(doc.value,selectedIds.value));selectedIds.value=[];inspectorId.value='';}
async function close(destination:'workbench'|'references'='workbench'){if(execution.busy.value){ElMessage.warning('节点操作仍在进行，请等待结果后退出');return;}if(store.dirty.value&&!await store.save()){ElMessage.warning('画布尚未保存，可先导出备份或重试保存');return;}if(destination==='references')emit('references');else emit('close');}
function exportFile(){const url=URL.createObjectURL(new Blob([JSON.stringify(doc.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${props.detail.project.projectName}-画布.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importFile(event:Event){const input=event.target as HTMLInputElement;try{const file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024)throw new Error('画布文件不能超过2MB');const imported=validateCanvas(JSON.parse(await file.text()));const part=cloneCanvasSelection(imported,imported.nodes.map(n=>n.id),{x:0,y:0});store.replace({...doc.value,nodes:[...doc.value.nodes,...part.nodes],edges:[...doc.value.edges,...part.edges]});await nextTick();await overview();}catch(e){ElMessage.error(e instanceof Error?e.message:'导入失败');}finally{input.value='';}}
async function template(){const kinds:CanvasKind[]=['text','script','image','image','audio','video'];const positions=[{x:100,y:60},{x:480,y:60},{x:100,y:380},{x:480,y:380},{x:100,y:710},{x:900,y:380}];const rows=kinds.map((kind,i)=>newCanvasNode(kind,positions[i]!));['故事大纲','剧本','主角造型','拍摄场景','角色声音','镜头 1'].forEach((name,i)=>rows[i]!.data.title=name);rows[2]!.data.model=props.imageModels[0]?.modelName || '';rows[3]!.data={...rows[3]!.data,purpose:'location',model:props.imageModels[0]?.modelName || ''};rows[4]!.data.actorNodeId=rows[2]!.id;rows[5]!.data={...rows[5]!.data,model:props.videoModels[0]?.modelName || '',order:1,resolution:'720p'};const links=[[0,1],[1,5],[2,4],[2,5],[3,5],[4,5]].map(([s,t])=>({id:crypto.randomUUID(),source:rows[s!]!.id,target:rows[t!]!.id}));store.replace({...doc.value,nodes:[...doc.value.nodes,...rows],edges:[...doc.value.edges,...links]});await nextTick();await overview();}
async function importProject(){try{await execution.refresh();const detail=execution.detail.value;const currentShots=detail.storyboards.some(s=>s.scriptId===detail.script?.id) ? detail.storyboards.filter(s=>s.scriptId===detail.script?.id) : detail.storyboards;const resources=await readShortDramaResource<{assets:FlowAsset[]}>(`/short-drama/${projectId}/visual-assets`);const graph=buildDramaFlowGraph({characters:detail.characters,locations:detail.locations,shots:currentShots,assets:resources.assets,voices:[]});
  const existing=new Set(doc.value.nodes.filter(n=>n.data.business).map(n=>`${n.data.business!.type}:${n.data.business!.id}:${n.data.business!.appearanceId || ''}`));const added:CanvasNode[]=[];const mapping=new Map<string,string>();
  for(const media of graph.media){const kind:CanvasKind=media.kind==='shot' ? 'video' : 'image';const actor=detail.characters.find(c=>c.id===media.characterId);const appearance=actor?.appearances?.find(a=>a.appearanceIndex===media.appearance);const type=media.kind==='shot' ? 'shot' : media.kind;const id=media.shot?.id || media.characterId || media.assetId || media.id.split(':').slice(1).join(':');const key=`${type}:${id}:${appearance?.id || ''}`;const prior=doc.value.nodes.find(n=>n.data.business&&`${n.data.business.type}:${n.data.business.id}:${n.data.business.appearanceId || ''}`===key);if(existing.has(key)&&prior){mapping.set(media.id,prior.id);continue;}
    const index=added.length;const n=newCanvasNode(kind,{x:kind==='video' ? 920+((media.shot?.sceneNo || 1)-1)%2*350 : 120+(index%2)*350,y:kind==='video' ? Math.floor(((media.shot?.sceneNo || 1)-1)/2)*350+60 : Math.floor(index/2)*330+60});let continuity:Record<string,any>={};if(media.shot)continuity=JSON.parse(media.shot.continuityJson || '{}');
    n.data={...n.data,title:media.title,content:media.shot?.sceneText || '',prompt:media.shot?.videoPrompt || appearance?.description || detail.locations.find(l=>`location:${l.id}`===media.id)?.summary || (resources.assets.find(a=>a.id===media.assetId) as any)?.prompt || media.subtitle,url:kind==='image' ? media.imageUrl || '' : '',model:continuity.video_model || (kind==='image' ? props.imageModels[0]?.modelName : props.videoModels[0]?.modelName) || '',purpose:media.kind==='character' ? 'character' : media.kind==='location' ? 'location' : 'prop',order:media.shot?.sceneNo,seconds:continuity.video_seconds,resolution:continuity.video_resolution || '720p',useStartFrame:continuity.video_use_start_frame,business:{id:id!,type,appearanceId:appearance?.id,scriptId:media.shot?.scriptId}};
    added.push(n);mapping.set(media.id,n.id);existing.add(key);
  }
  const links=graph.links.filter(e=>mapping.has(e.source)&&mapping.has(e.target)).map(e=>({id:crypto.randomUUID(),source:mapping.get(e.source)!,target:mapping.get(e.target)!}));
  if(detail.script?.id&&!existing.has(`script:${detail.script.id}:`)){const n=newCanvasNode('script',{x:-250,y:60});n.data={...n.data,title:detail.script.scriptName,content:detail.script.scriptText || '',business:{id:detail.script.id,type:'script'}};added.push(n);}
  for(const shot of currentShots){const continuity=JSON.parse(shot.continuityJson || '{}');const target=mapping.get(`shot:${shot.id}`);for(const actorId of Array.isArray(continuity.voice_speakers) ? continuity.voice_speakers : []){let audio=[...doc.value.nodes,...added].find(n=>n.kind==='audio'&&n.data.business?.id===String(actorId));if(!audio){const actor=[...doc.value.nodes,...added].find(n=>n.data.business?.type==='character'&&n.data.business.id===String(actorId));if(!actor)throw new Error('原声音引用缺少角色，请在原工作台修复');audio=newCanvasNode('audio',{x:120,y:added.length*180+100});audio.data={...audio.data,title:`${actor.data.title} · 声音`,actorNodeId:actor.id,business:{id:String(actorId),type:'voice'}};added.push(audio);}if(target)links.push({id:crypto.randomUUID(),source:audio.id,target});}
    if(target&&continuity.manual_start_frame?.url){const prior=[...doc.value.nodes,...added].find(n=>n.kind==='image'&&n.data.purpose==='frame'&&n.data.url===continuity.manual_start_frame.url);const frame=prior || newCanvasNode('image',{x:560,y:(shot.sceneNo-1)*320});if(!prior){frame.data={...frame.data,title:`镜 ${shot.sceneNo} · 首帧`,purpose:'frame',url:continuity.manual_start_frame.url};added.push(frame);}links.push({id:crypto.randomUUID(),source:frame.id,target});}
  }
  const dedup=links.filter(e=>!doc.value.edges.some(old=>old.source===e.source&&old.target===e.target));store.replace({...doc.value,nodes:[...doc.value.nodes,...added],edges:[...doc.value.edges,...dedup]});await nextTick();await overview();ElMessage.success(`已导入 ${added.length} 个节点`);
}catch(e){ElMessage.error(e instanceof Error?e.message:'项目素材导入失败');}}
async function upload(event:Event){const input=event.target as HTMLInputElement;const n=selected.value;try{const file=input.files?.[0];if(!file||!n)return;if(!n.data.model&&!props.imageModels[0]?.modelName)throw new Error('请先配置图片模型');const url=await uploadReferenceImage(file,n.data.model || props.imageModels[0]!.modelName!);patch(n.id,{url});}catch(e){ElMessage.error(e instanceof Error?e.message:'上传失败');}finally{input.value='';}}
async function run(action:'save'|'generate'|'query'|'accept'|'plan'){const id=selected.value?.id;if(!id||!await store.save())return;const result=await (action==='save' ? execution.sync(id) : execution[action](id));await store.save();if(result&&action==='plan')await importProject();}
async function restore(){if(selected.value?.data.business)await props.actions.restore(selected.value.data.business.id);await execution.refresh();}
async function command(name:string){try{if(name==='undo')store.undo();else if(name==='redo')store.redo();else if(name==='duplicate')duplicate();else if(name==='copy')copy();else if(name==='paste')paste();else if(name==='group')group();else if(name==='ungroup')ungroup();else if(name==='remove')remove();else if(name==='inspect')inspect(menu.value?.target || selectedIds.value[0] || '');else if(name==='unlink')store.replace({...doc.value,edges:doc.value.edges.filter(e=>e.id!==menu.value?.edge)});else if(name==='overview')await overview();else if(name==='close')await close();else if(name==='references')await close('references');else if(name==='new'){if(await store.save())emit('new');}else if(name==='save')await store.save();else if(name==='compose'){await execution.refresh();composeOpen.value=true;}else if(name==='template')await template();else if(name==='importProject')await importProject();else if(name==='export')exportFile();else if(name==='workflow'||name==='storyboard'){mode.value=name;if(name==='workflow'){await nextTick();await initialize();}}else if(name==='select'||name==='hand')tool.value=name;else if(name==='zoomIn'||name==='zoomOut'){await (name==='zoomIn' ? zoomIn() : zoomOut());rememberView();}else if(name==='edges')showEdges.value=!showEdges.value;else if(name==='help')await ElMessageBox.alert('空白处右键 / Tab：新建节点\nShift 拖动：框选；Ctrl 点击：多选\nCtrl C / V / D：复制、粘贴、创建副本\nCtrl G / Ctrl Shift G：成组、解组\nCtrl Z / Ctrl Shift Z：撤销、重做\nDelete：从画布移除；Ctrl S：保存\n连线到空白处：创建下游节点\nV / H：选择、抓手；Ctrl 0：适应画布','画布快捷键',{confirmButtonText:'知道了'});}catch(e){ElMessage.warning(e instanceof Error?e.message:'操作失败');}menu.value=undefined;}
function keyboard(event:KeyboardEvent){if(directorId.value)return;const target=event.target as HTMLElement;if(target.closest('input,textarea,select,[contenteditable=true],.el-popper,.el-overlay'))return;if(event.key==='Escape'){if(menu.value)menu.value=undefined;else if(inspectorId.value)inspectorId.value='';else void close();return;}let action='';const ctrl=event.ctrlKey||event.metaKey;const key=event.key.toLowerCase();if(ctrl){action=key==='z' ? event.shiftKey ? 'redo':'undo' : key==='y' ? 'redo' : ({s:'save',c:'copy',v:'paste',d:'duplicate',g:event.shiftKey?'ungroup':'group','0':'overview'} as Record<string,string>)[key] || '';if(key==='a'){event.preventDefault();selectedIds.value=doc.value.nodes.map(n=>n.id);return;}}else if(event.key==='Delete'||event.key==='Backspace')action='remove';else if(key==='v')action='select';else if(key==='h')action='hand';else if(event.key==='Enter')action='inspect';else if(event.key==='Tab'){event.preventDefault();const rect=pane.value!.getBoundingClientRect();menu.value={x:rect.left+160,y:rect.top+100,point:project({x:160,y:100})};return;}if(action){event.preventDefault();void command(action);}}
function outside(event:PointerEvent){if(!(event.target as Element)?.closest('.canvas-context'))menu.value=undefined;}
onMounted(async()=>{root.value?.focus();document.addEventListener('keydown',keyboard);document.addEventListener('pointerdown',outside);await store.load();});
onUnmounted(()=>{document.removeEventListener('keydown',keyboard);document.removeEventListener('pointerdown',outside);});
</script>

<template>
  <div ref="root" class="flow-studio" role="dialog" aria-modal="true" aria-label="短剧流程编辑器" tabindex="-1">
    <CanvasToolbar :title="detail.project.projectName" :project-shot-count="projectShotCount" :count="doc.nodes.length" :selected="selectedIds.length" :saving="store.saving.value" :dirty="store.dirty.value" :ready="store.ready.value" :can-undo="store.canUndo.value" :can-redo="store.canRedo.value" :zoom="Math.round(viewport.zoom*100)" :mode="mode" :tool="tool" :error="store.error.value" @action="command" @add="add" @file="importFile" />
    <div class="studio-body"><main ref="pane" class="studio-canvas">
